import collections
def solve(inp, sep=0):
    # find full separator rows/cols
    H=len(inp);W=len(inp[0])
    sr=[i for i in range(H) if all(x==sep for x in inp[i])]
    sc=[j for j in range(W) if all(inp[i][j]==sep for i in range(H))]
    rbands=[];s=0
    for i in sr+[H]:
        if i>s:rbands.append((s,i));s=i+1
    cbands=[];s=0
    for j in sc+[W]:
        if j>s:cbands.append((s,j));s=j+1
    out=[]
    for s1,e1 in rbands:
        row=[]
        for s2,e2 in cbands:
            vals=[inp[i][j] for i in range(s1,e1) for j in range(s2,e2)]
            cnt=collections.Counter(vals)
            # ignore pure-sep? just use nonsep counts
            nz={k:v for k,v in cnt.items() if k!=sep}
            if not nz: row.append(sep); continue
            top=max(nz.values())
            major=[k for k,v in nz.items() if v==top]
            row.append(major[0] if len(major)==1 else nz.keys().__iter__().__next__())
        out.append(row)
    return out
